import math
from itertools import combinations

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_min_m(n, k):
    # Start with the smallest possible m
    m = 4 * n
    while True:
        # Generate all numbers from 1 to m
        numbers = list(range(1, m + 1))
        # Filter out numbers that are not multiples of k
        numbers = [x for x in numbers if x % k == 0]
        # Try to form n sets of rank k
        sets = []
        for _ in range(n):
            found = False
            for comb in combinations(numbers, 4):
                if all(gcd(comb[i], comb[j]) == k for i in range(4) for j in range(i + 1, 4)):
                    sets.append(list(comb))
                    for num in comb:
                        numbers.remove(num)
                    found = True
                    break
            if not found:
                break
        if len(sets) == n:
            return m, sets
        m += 1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    k = int(data[1])
    m, sets = find_min_m(n, k)
    print(m)
    for s in sets:
        print(' '.join(map(str, s)))

if __name__ == "__main__":
    main()
